\title{Non-Embeddability of the Petersen Graph into\\ Bipartite Abelian Cayley Graphs}
\author{Aristotle}
\date{2026-07-01}

\begin{document}
\maketitle

\begin{abstract}
We prove that the Petersen graph does not admit an isometric embedding into any
bipartite Cayley graph of a finite abelian group --- in particular, into any
hypercube $Q_k = \Cay\big((\ZZ/2)^k, \{e_1,\dots,e_k\}\big)$. Our argument
isolates two independent ingredients. The first is a purely metric obstruction,
valid for every number of colors: an isometric map pulls back proper colorings
from the host to the source, so a graph requiring more than $n$ colors cannot
embed isometrically into any $n$-colorable graph. The second is an algebraic
certificate specific to abelian Cayley graphs: the existence of an additive
character $\psi \colon A \to \ZZ/2$ that sends every element of the connection
set to $1$ is equivalent to a proper $2$-coloring, so a single group
homomorphism witnesses bipartiteness. Since the Petersen graph has odd girth
five and chromatic number three, combining the two ingredients rules out every
bipartite abelian Cayley host at once. We recover, and strengthen to the
isometric setting, the classical fact that the Petersen graph is not a partial
cube, and we frame the non-bipartite case as a family of conjectures.
\end{abstract}

\noindent\textbf{Keywords:} Petersen graph, Cayley graph, abelian group,
isometric embedding, partial cube, hypercube, bipartite graph, graph coloring,
odd girth, Kneser graph.

\section{Introduction}

The Petersen graph $P$ is the standard source of counterexamples in graph
theory: a $3$-regular, vertex-transitive graph on ten vertices with girth five
and chromatic number three. Among its extremal properties is that it is
\emph{not a partial cube} --- it does not embed isometrically into any
hypercube. Partial cubes are exactly the graphs encodable by binary addresses so
that graph distance equals Hamming distance, and the class is central to metric
graph theory and the geometry of data.

Hypercubes are the most familiar members of a much larger family: the Cayley
graphs of finite abelian groups. It is natural to ask whether the failure of the
Petersen graph to embed into hypercubes is a shadow of a broader phenomenon.
Could a more exotic abelian group, with a cleverly chosen generating set, host
the Petersen graph isometrically? This paper settles the question for all
\emph{bipartite} abelian Cayley hosts and frames the remaining non-bipartite
case as a precise conjecture. We separate the obstruction into two logically
independent halves: a metric principle valid for every number of colors, and a
bipartite certificate specific to abelian Cayley graphs that operates only at
the level $n=2$.

\section{Definitions}

Graphs are simple, undirected, and connected unless stated otherwise. We write
$\dist_G(u,v)$ for the shortest-path distance in $G$.

\begin{definition}[Distance and adjacency]
In a connected graph $G$, the distance $\dist_G(u,v)$ is the number of edges on
a shortest $u$--$v$ path. Two distinct vertices are adjacent precisely when their
distance equals $1$.
\end{definition}

\begin{definition}[Isometric embedding]
A map $f \colon V(G) \to V(H)$ is an isometric embedding if
$\dist_H(f(u), f(v)) = \dist_G(u,v)$ for all $u,v \in V(G)$. Such a map is
injective and sends edges to edges.
\end{definition}

\begin{definition}[Proper coloring]
A proper $n$-coloring of $G$ is a map $c \colon V(G) \to C$ into an $n$-element
set with $c(u) \neq c(v)$ whenever $u,v$ are adjacent. $G$ is $n$-colorable if
one exists, and bipartite iff it is $2$-colorable, equivalently iff it has no
odd cycle.
\end{definition}

\begin{definition}[Cayley graph of an abelian group]
Let $A$ be an additive abelian group and $S \subseteq A$ a connection set with
$S = -S$ (symmetry) and $0 \notin S$ (looplessness). The Cayley graph
$\Cay(A,S)$ has vertex set $A$, with $g,h$ adjacent iff $h - g \in S$.
\end{definition}

\begin{definition}[Hypercube]
For $k \in \NN$, $Q_k = \Cay\big((\ZZ/2)^k, \{e_i : 1 \le i \le k\}\big)$, where
$e_i$ is the $i$-th standard basis vector. Its distance is the Hamming distance.
\end{definition}

\begin{definition}[Partial cube]
A graph is a partial cube if it embeds isometrically into $Q_k$ for some $k$.
\end{definition}

\begin{definition}[Petersen graph]
The Petersen graph $P$ is the Kneser graph $K(5,2)$: vertices are the ten
two-element subsets of $\{1,\dots,5\}$, adjacent iff disjoint. It is $3$-regular,
vertex-transitive under $S_5$, has girth five, chromatic number three, and odd
girth five.
\end{definition}

\section{The metric obstruction}

\begin{lemma}[Colorings pull back along isometries]\label{lem:pullback}
Let $f \colon V(G) \to V(H)$ be an isometric embedding and $n \in \NN$. If $H$
is $n$-colorable, then $G$ is $n$-colorable.
\end{lemma}

\begin{proof}
Let $c$ be a proper $n$-coloring of $H$. Define $c' = c \circ f$. For an edge
$uv$ of $G$ we have $\dist_G(u,v) = 1$, so by isometry
$\dist_H(f(u),f(v)) = 1$, hence $f(u),f(v)$ are adjacent in $H$ and
$c(f(u)) \neq c(f(v))$. Thus $c'(u) \neq c'(v)$ and $c'$ is proper.
\end{proof}

The isometry hypothesis is used exactly once --- to convert a $G$-edge into an
$H$-edge --- and cannot be dropped: folding a triangle $K_3$ onto an edge $K_2$
is a homomorphism but not an isometric embedding, and would falsely pull back a
$2$-coloring to the non-bipartite $K_3$.

\begin{theorem}[Chromatic obstruction]\label{thm:chrom}
If $G$ is not $n$-colorable and $H$ is $n$-colorable, there is no isometric
embedding of $G$ into $H$.
\end{theorem}

\begin{proof}
An isometric embedding would force $G$ to be $n$-colorable by
Lemma~\ref{lem:pullback}, a contradiction.
\end{proof}

Theorem~\ref{thm:chrom} holds for every $n$. At $n=2$ it says an isometric image
inside a bipartite graph must itself be bipartite.

\section{The bipartite certificate for abelian Cayley graphs}

\begin{lemma}[Character certificate]\label{lem:char}
Let $A$ be abelian and $S$ a connection set. If there is an additive character
$\psi \colon A \to \ZZ/2$ with $\psi(s) = 1$ for all $s \in S$, then $\Cay(A,S)$
is bipartite, with $\psi$ itself a proper $2$-coloring.
\end{lemma}

\begin{proof}
Color each vertex $g$ by $\psi(g) \in \ZZ/2$. If $g,h$ are adjacent then
$h - g \in S$, so
$\psi(h) - \psi(g) = \psi(h-g) = 1 \neq 0$, whence $\psi(g) \neq \psi(h)$.
\end{proof}

For $Q_k$ the certificate is the coordinate-sum parity
$\psi(x) = \sum_{i=1}^k x_i$, which is additive and sends each $e_i$ to $1$;
hence $Q_k$ is bipartite with even- and odd-weight strings as color classes.

\section{Main results}

\begin{proposition}[Petersen is not bipartite]\label{prop:notbip}
The Petersen graph $P$ is not $2$-colorable.
\end{proposition}

\begin{proof}
$P$ contains a $5$-cycle (its girth is five), and a graph with an odd cycle
cannot be $2$-colored, since alternating two colors around an odd cycle is
impossible. Equivalently $\chi(P) = 3$.
\end{proof}

\begin{theorem}[Main theorem]\label{thm:main}
Let $A$ be a finite abelian group with connection set $S$, and suppose there is
an additive character $\psi \colon A \to \ZZ/2$ with $\psi(s) = 1$ for all
$s \in S$. Then the Petersen graph does not embed isometrically into
$\Cay(A,S)$: for every $f \colon V(P) \to A$,
\[
\neg\,\forall u,v \in V(P) \colon
\dist_{\Cay(A,S)}(f(u),f(v)) = \dist_P(u,v).
\]
\end{theorem}

\begin{proof}
By Lemma~\ref{lem:char}, $\Cay(A,S)$ is $2$-colorable; by
Proposition~\ref{prop:notbip}, $P$ is not. Theorem~\ref{thm:chrom} with $n=2$
denies any isometric embedding.
\end{proof}

\begin{corollary}[Isometric partial-cube obstruction]\label{cor:cube}
The Petersen graph is not a partial cube.
\end{corollary}

\begin{proof}
Apply Theorem~\ref{thm:main} to $A = (\ZZ/2)^k$, $S = \{e_1,\dots,e_k\}$, and
the coordinate-sum character, which sends each $e_i$ to $1$.
\end{proof}

Corollary~\ref{cor:cube} recovers and re-frames the classical fact: the
obstruction is not special to hypercubes but is a uniform consequence of the
host being a bipartite abelian Cayley graph. The hypercube supplies an explicit
non-vacuous family of hosts.

\section{Algorithms}

\begin{algorithm}[Character-based bipartiteness certificate]
Given a finite abelian group $A$ and connection set $S$, enumerate
$\mathrm{Hom}(A, \ZZ/2)$ and test whether any character sends all of $S$ to $1$.
For elementary abelian $2$-groups this reduces to a linear system over
$\mathbb{F}_2$.
\end{algorithm}

\begin{algorithm}[Coloring pullback / embedding refutation]
Given an alleged isometric embedding $f \colon V(P) \to A$ into a
certified-bipartite host, form $v \mapsto \psi(f(v))$ and exhibit a
monochromatic edge of $P$ (guaranteed since $P$ is not $2$-colorable).
\end{algorithm}

\begin{algorithm}[Odd-cycle witness]
Breadth-first layering finds an edge inside a layer, closing an odd cycle. On
$P$ this returns a $5$-cycle, the obstruction of
Proposition~\ref{prop:notbip}. Complexity is linear.
\end{algorithm}

\section{Discussion and future directions}

The architecture ``metric obstruction (any $n$) $+$ cheap bipartite certificate
($n=2$ via a character)'' pinpoints the reach of the method. It is silent about
non-bipartite abelian hosts (e.g. $C_5 = \Cay(\ZZ/5,\{\pm 1\})$), where no such
character exists.

\begin{conjecture}[Grand non-embeddability]
The Petersen graph admits no isometric embedding into $\Cay(A,S)$ for any finite
abelian group $A$ and symmetric connection set $S$, including generating sets
producing odd cycles. Commutativity forces shortest-path directions to behave
like independent coordinates, incompatible with the Petersen graph's fivefold
symmetry without collapsing non-adjacent vertices to equal distance profiles.
\end{conjecture}

\begin{conjecture}[Odd girth versus abelian coordinates]
If a vertex-transitive graph of odd girth at least five embeds isometrically
into a finite abelian Cayley graph, then it is a Cartesian product of even
cycles and complete graphs on at most two vertices. In particular no such
embedding exists for Cartesian-prime graphs like the Petersen graph.
\end{conjecture}

\begin{conjecture}[Kneser graphs]
For every $n \ge 5$, the Kneser graph $K(n,2)$ (the Petersen graph is $n=5$)
admits no isometric embedding into any finite abelian Cayley graph, because the
disjointness metric encodes an odd $5$-cycle for every $n \ge 5$.
\end{conjecture}

\section{Applications}

Isometric embeddings into hypercubes and abelian Cayley graphs underlie
low-distortion binary coding, where graph proximity becomes coordinate
proximity. Theorem~\ref{thm:main} and Corollary~\ref{cor:cube} mark a hard
boundary: no additive addressing scheme on a bipartite abelian group can
faithfully encode the Petersen metric, and --- conjecturally --- no abelian
scheme can at all.

\section{Conclusion}

The Petersen graph does not embed isometrically into any bipartite Cayley graph
of a finite abelian group. The proof factors into a fully general metric
pullback of colorings and a one-line character certificate of bipartiteness,
isolating the non-bipartite frontier where the grand conjecture lives.

\end{document}

